// The verification rules the Rust CLI copies (cli/crates/craft-review/src/settle.rs, harm.rs, verify.rs) held to the
// engines' own by one shared file, content/parity/verify-cases.json, a golden file the CLI owns
// (cli/crates/craft-review/src/parity.rs; regenerated by `CRAFT_UPDATE_PARITY=1 cargo test -p craft-review parity`):
// the constants; for one finding and one verdict the tier, the final severity and the route; for a panel of votes the
// same and its why, discarded votes and verified harm; and whether a deciding pair agrees.
import { test } from 'vitest'
import assert from 'node:assert/strict'
import cases from '../content/parity/verify-cases.json' with { type: 'json' }
import { BATCH_SIZE, CRITICAL_TIER_RULES, DEMOTE, decideTier, isVerdictShaped, tierFromVotes, verifyTier, votesAgree } from './review-verify.mjs'
import { harmRaise } from './harm-verify.mjs'
import { capByHarm } from './harm-cap.mjs'
import { HARM_CEILING, HARM_LEVELS } from './harm-levels.mjs'

test('the constants the CLI copies are the engines\' own', () => {
  assert.equal(cases.batchSize, BATCH_SIZE)
  assert.deepEqual(cases.criticalTierRules, [...CRITICAL_TIER_RULES])
  assert.deepEqual(cases.demote, DEMOTE)
  assert.deepEqual(cases.harmCeiling, HARM_LEVELS.map(l => [l, HARM_CEILING[l]]))
})

for (const c of cases.cases) {
  test(`parity: ${c.name}`, () => {
    /** @type {import('./review-schemas.mjs').Finding} */
    const finding = structuredClone(c.finding)
    // The vote is data as the agent returned it; isVerdictShaped guards it.
    const live = /** @type {Array<import('./review-schemas.mjs').VerdictAnswer>} */ (/** @type {unknown} */ (c.vote ? [c.vote] : []))
    // The pool's order for a panel of one: the tier and its demotions, the verified-harm raise, then the cap.
    const settled = capByHarm(harmRaise(decideTier(finding, live, live.filter(isVerdictShaped))))
    assert.deepEqual({ tier: settled.tier, severity: settled.severity }, { tier: c.expected.tier, severity: c.expected.severity })
    assert.equal(verifyTier(finding), c.expected.route)
  })
}

for (const c of cases.panelCases) {
  test(`panel parity: ${c.name}`, () => {
    /** @type {import('./review-schemas.mjs').Finding} */
    const finding = structuredClone(c.finding)
    // The pool's order for a panel: the votes' tier and its demotions, the verified-harm raise, then the cap.
    // The votes are data as the agents returned them, off-schema ones included: tierFromVotes guards them itself.
    const votes = /** @type {Array<import('./review-schemas.mjs').VerdictAnswer | null>} */ (/** @type {unknown} */ (c.votes))
    const settled = capByHarm(harmRaise(tierFromVotes(finding, votes)))
    /** @type {Record<string, unknown>} */
    const want = c.expected
    /** @type {Record<string, unknown>} */
    const got = { tier: settled.tier, severity: settled.severity }
    for (const k of ['why', 'votesDiscarded', 'harmVerified']) if (k in want) got[k] = settled[k]
    assert.deepEqual(got, want)
  })
}

for (const c of cases.agreeCases) {
  test(`deciding-pair parity: ${c.name}`, () => {
    const [a, b] = /** @type {Array<import('./review-schemas.mjs').VerdictAnswer>} */ (/** @type {unknown} */ (c.pair))
    assert.equal(votesAgree(a, b), c.agree)
  })
}
